#!/usr/bin/env node
/* 源码模块 -> 运行包。项目要支持 file:// 直开，不能依赖 ES Modules；
 * 因此界面按业务边界拆成 src/ 下的片段，构建时按顺序合回一个 IIFE 运行文件。
 * 用法：node tools/build.js
 */
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const banner = [
  '/* ============================================================================',
  ' * AUTO-GENERATED by tools/build.js from src/ — 请勿直接修改本文件。',
  ' * 源码已按业务模块拆分；修改 src/ 后运行 node tools/build.js 重新生成。',
  ' * ==========================================================================*/',
  ''
].join('\n');

const bundles = [
  {
    name: '古建界面',
    out: 'js/app.js',
    files: [
      'src/ancient-ui/00-shell.js',
      'src/ancient-ui/10-env-editor.js',
      'src/ancient-ui/20-building-editor.js',
      'src/ancient-ui/30-controls.js',
      'src/ancient-ui/40-render.js',
      'src/ancient-ui/50-camera.js',
      'src/ancient-ui/60-demo.js',
      'src/ancient-ui/70-grid.js',
      'src/ancient-ui/80-drag.js',
      'src/ancient-ui/90-interactions.js',
      'src/ancient-ui/95-export.js',
      'src/ancient-ui/97-events.js',
      'src/ancient-ui/99-boot.js'
    ]
  },
  {
    name: '城池界面',
    out: 'js/city-app.js',
    files: [
      'src/city-ui/00-shell.js',
      'src/city-ui/10-controls.js',
      'src/city-ui/20-render.js',
      'src/city-ui/30-interactions.js',
      'src/city-ui/40-export.js',
      'src/city-ui/50-ancient-import.js',
      'src/city-ui/60-events.js',
      'src/city-ui/70-boot.js'
    ]
  },
  {
    name: '建筑装配',
    out: 'js/gf-build.js',
    files: [
      'src/ancient-build/00-common.js',
      'src/ancient-build/10-dwellings.js',
      'src/ancient-build/20-gates.js',
      'src/ancient-build/30-courtyard.js',
      'src/ancient-build/40-layout.js',
      'src/ancient-build/50-compounds.js',
      'src/ancient-build/60-garden.js',
      'src/ancient-build/70-city.js',
      'src/ancient-build/80-assembly.js'
    ]
  }
];

function buildBundle(b) {
  const parts = b.files.map((rel) => {
    const p = path.join(root, rel);
    if (!fs.existsSync(p)) throw new Error('缺少模块：' + rel);
    return fs.readFileSync(p, 'utf8');
  });
  const output = banner + parts.join('\n');
  const dest = path.join(root, b.out);
  const current = fs.existsSync(dest) ? fs.readFileSync(dest, 'utf8') : '';
  const lines = output.split('\n').length;
  if (check) {
    if (current !== output) {
      console.error(`[check] ${b.out} 与 src/ 不一致，请运行 node tools/build.js`);
      failed = true;
    } else {
      console.log(`[check] ${b.name} → ${b.out} ok (${b.files.length} modules, ${lines} lines)`);
    }
    return;
  }
  fs.writeFileSync(dest, output, 'utf8');
  console.log(`[build] ${b.name} → ${b.out}  (${b.files.length} modules, ${lines} lines)`);
}

const check = process.argv.includes('--check');
let failed = false;
for (const b of bundles) buildBundle(b);
if (check && failed) process.exitCode = 1;
else if (check) console.log('[check] 运行包与源码一致。');
else console.log('[build] 完成。运行包已更新。');
